//! Oracle-generated governance fixtures: the nested `charter context --json`
//! contract, the org-charter floor/block, the profile catalogue, and real
//! cross-language lock contention.
//!
//! Every fixture is a temporary project; nothing here touches a real checkout's
//! runtime, home or config. The comparisons are generated by the pinned Python
//! oracle at test time, so a contract drift on either side reddens instead of
//! being frozen as a hand-written expectation.
//!
//! The payload comparison is EXACT: typed arrays are compared entry-for-entry
//! (full nested `body`, `references[]`, `delivery`), and the top-level link set
//! is compared as the same array (order and content). There is no
//! subset/extras/`body.id`-only leniency.

mod support;

use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Duration;

use serde_json::{Value, json};
use sk_charter::ArtifactKind;
use sk_doctrine::{
    ActivationLedger, ActivationPlan, ActivationTransaction, ContextInputs, ContextRequest,
    DoctrineError, IdentityIndex, ProfileRepository, acquire_synthesis_lock, build_action_context,
    context_roots, load_activation_ledger, load_graph_or_dir, load_org_charter_policy,
    load_org_pack, merge_three_layers, read_org_required_provenance, read_org_required_tokens,
    required_floor, resolve_activation_source, scan_all, synthesis_lock_path,
};

struct Fixture {
    _temp: tempfile::TempDir,
    project: PathBuf,
    packs: PathBuf,
}

fn write(path: &Path, text: &str) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, text).unwrap();
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for entry in fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let source = entry.path();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_tree(&source, &target);
        } else if entry.file_type().unwrap().is_file() {
            fs::copy(&source, &target).unwrap();
        }
    }
}

fn git(repo: &Path, args: &[&str]) {
    let output = Command::new("git")
        .args(args)
        .current_dir(repo)
        .output()
        .expect("run git");
    assert!(
        output.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

fn init_project(project: &Path) {
    fs::create_dir_all(project).unwrap();
    git(project, &["init", "-q", "-b", "main"]);
    git(project, &["config", "user.email", "oracle@example.invalid"]);
    git(project, &["config", "user.name", "Oracle Fixture"]);
}

fn fixture() -> Fixture {
    fixture_with_git(true)
}

/// The same fixture as [`fixture`], optionally WITHOUT a Git repository.
///
/// The reference's charter-config reads (`load_directives_config`,
/// `load_governance_config`, `resolve_project_governance`) anchor on
/// `charter.resolution.resolve_canonical_repo_root`, so a plain directory is a
/// distinct, supported input whose JSON payload degrades differently.
fn fixture_with_git(git_repository: bool) -> Fixture {
    let temp = tempfile::tempdir().unwrap();
    let packs = temp.path().join("packs");
    let project = temp.path().join("project");
    let org = packs.join("org");
    copy_tree(
        &support::repository_root().join("packs/built-in"),
        &packs.join("built-in"),
    );
    if git_repository {
        init_project(&project);
    } else {
        fs::create_dir_all(&project).unwrap();
    }

    write(
        &org.join("pack.yaml"),
        "pack_id: 01ARZ3NDEKTSV4RRFFQ69G5FAV\nname: acme\npack_level: org\n",
    );
    write(
        &org.join("drg/fragment.yaml"),
        "pack_name: acme\nnodes: []\nedges: []\n",
    );
    write(
        &org.join("org-charter.yaml"),
        "schema_version: 2\norg_name: Acme\nrequired_directives: [DIRECTIVE_003]\ngovernance_policies:\n  - field: commits\n    value: signed\n",
    );
    write(
        &project.join(".kittify/config.yaml"),
        &format!(
            "charter_packs:\n  org:\n    packs:\n      - name: acme\n        local_path: {}\n",
            org.display()
        ),
    );
    write(
        &project.join(".kittify/charter/activation.yaml"),
        "activated_directives:\n- DIRECTIVE_001\ndeactivated_directives:\n- 024-locality-of-change\nactivated_tactics:\n- acceptance-test-first\nmission_type_activations:\n- software-dev\n",
    );
    write(
        &project.join(".kittify/charter/charter.yaml"),
        "governance:\n  charter:\n    selected_directives:\n      - DIRECTIVE_024\n    governance_references:\n      - docs/context.md\n      - missing.md\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n",
    );
    write(&project.join("docs/context.md"), "context\n");

    Fixture {
        _temp: temp,
        project,
        packs,
    }
}

fn set_ledger(fixture: &Fixture, text: &str) {
    write(
        &fixture.project.join(".kittify/charter/activation.yaml"),
        text,
    );
}

fn set_org_charter(fixture: &Fixture, text: &str) {
    write(&fixture.packs.join("org/org-charter.yaml"), text);
}

fn run_oracle(fixture: &Fixture, script: &str) -> Value {
    let child = Command::new(support::python())
        .arg("-c")
        .arg(script)
        .current_dir(&fixture.project)
        .envs(support::oracle_env(&fixture.packs))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn python oracle");
    let output = child.wait_with_output().expect("oracle output");
    assert!(
        output.status.success(),
        "oracle failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("oracle emitted JSON")
}

fn native_payload(fixture: &Fixture) -> Value {
    native_payload_result(fixture).expect("native context")
}

fn native_payload_result(fixture: &Fixture) -> Result<Value, DoctrineError> {
    let project = fixture.project.as_path();
    let (built_in_root, org_roots, project_root) = context_roots(project).expect("roots");
    let built_in = load_graph_or_dir(&built_in_root).expect("built-in graph");
    let mut fragments = Vec::new();
    for (index, root) in org_roots.iter().enumerate() {
        let name = root
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("org")
            .to_owned();
        fragments.push(load_org_pack(&name, root, index + 1).expect("org pack"));
    }
    // A project pack overlay contributes its own graph layer (the reference
    // `load_validated_graph(..., include_project=True)`); the base fixture has
    // none, so this is a no-op there.
    let project_graph = project_root
        .as_deref()
        .filter(|root| sk_doctrine::has_graph_files(root))
        .map(|root| load_graph_or_dir(root).expect("project graph"));
    let report = merge_three_layers(&built_in, &fragments, project_graph.as_ref()).expect("merge");
    let identity = IdentityIndex::from_roots(&built_in_root, &org_roots, project_root.as_deref());
    let profiles = ProfileRepository::load(&built_in_root, &org_roots, project_root.as_deref())
        .expect("profiles");
    let ledger = load_activation_ledger(project).expect("ledger");
    let floor = required_floor(project, &identity)
        .expect("required floor")
        .into_map();
    let inputs = ContextInputs {
        graph: &report.graph,
        ledger: &ledger,
        identity: &identity,
        profiles: &profiles,
        project_root: project,
        required_floor: &floor,
        project_warnings: &[],
    };
    let mut request = ContextRequest::new("implement");
    request.mission_type = Some("software-dev");
    // A first-load bootstrap context resolves at the reference minimum depth (2);
    // a repeat load drops to 1. The fixture has no context-state.json.
    request.depth = 2;
    build_action_context(&inputs, &request).map(|context| context.to_json())
}

const ORACLE_SCRIPT: &str = r#"
import json
from pathlib import Path
from charter.activation.context import build_charter_context_json
from charter.activation.org_charter_loader import load_org_charter_json_block
from charter.activation.synthesizer.synthesis_lock import synthesis_lock_path

repo = Path.cwd()
payload = build_charter_context_json(repo, action="implement", mission_type="software-dev")
org = load_org_charter_json_block([Path(__import__("os").environ["SPEC_KITTY_PACKS_ROOT"]) / "org"])
print(json.dumps({
    "payload": payload,
    "org_charter": org,
    "synthesis_lock_path": str(synthesis_lock_path(repo)),
}))
"#;

/// Assert the complete payload matches the reference exactly.
///
/// Every typed array is compared as a whole: identical ids, order, entry key
/// set, `source`/`title`/`summary`/`delivery`, the full nested `body` model dump
/// and the full `references[]` list. The top-level link set is compared as the
/// same array (order and content), never as a subset.
fn assert_payload_matches_oracle(native: &Value, expected: &Value) {
    assert_eq!(
        native["context_schema_version"],
        expected["context_schema_version"]
    );
    assert_eq!(native["action"], expected["action"]);
    assert_eq!(native["mode"], expected["mode"]);
    assert_eq!(native["directives_source"], expected["directives_source"]);
    assert_eq!(native["all_directives"], expected["all_directives"]);
    assert_eq!(native["project_charter"], expected["project_charter"]);
    assert_eq!(
        native["governance_references"],
        expected["governance_references"]
    );
    for key in [
        "directives",
        "tactics",
        "styleguides",
        "toolguides",
        "procedures",
    ] {
        assert_eq!(
            native[key], expected[key],
            "{key}: exact nested entries (id/source/title/summary/references/delivery/body)"
        );
    }
    assert_eq!(
        native["references"], expected["references"],
        "exact top-level link set (order + content)"
    );
}

/// The native diagnostics must match the reference EXACTLY for every
/// diagnostic the native contract models: same order, same code, same message.
///
/// The one declared breadth gap is the tools / template-set `FALLBACK_APPLIED`
/// pair, which the reference's resolver emits and the native project-governance
/// resolution does not model yet (README "Remaining full-charter gaps"). Those
/// two entries are removed from the oracle side before comparison — no other
/// entry may differ, and the native side must never fabricate a
/// `FALLBACK_APPLIED`. This replaces the earlier code-subset check, which could
/// not see a duplicated `UNKNOWN_SELECTION_DROPPED` or a drifted message.
fn assert_diagnostics_match_oracle(native: &Value, expected: &Value) {
    let expected: Vec<Value> = expected["diagnostics"]
        .as_array()
        .expect("oracle diagnostics")
        .iter()
        .filter(|diagnostic| diagnostic["code"] != "FALLBACK_APPLIED")
        .cloned()
        .collect();
    let native_diagnostics = native["diagnostics"]
        .as_array()
        .expect("native diagnostics")
        .clone();
    assert!(
        native_diagnostics
            .iter()
            .all(|diagnostic| diagnostic["code"] != "FALLBACK_APPLIED"),
        "native must not fabricate the unported FALLBACK_APPLIED diagnostics: {native_diagnostics:?}"
    );
    assert_eq!(
        Value::Array(native_diagnostics),
        Value::Array(expected),
        "exact governance-resolution diagnostics (order, code and message)"
    );
}

#[test]
fn nested_context_matches_the_oracle_generated_fixture() {
    let fixture = fixture();
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    assert_eq!(
        native["directives_source"].as_str(),
        Some("activation+charter+project_local")
    );
    // Non-vacuity: the fixture really delivers nested bodies and a link set.
    assert!(expected["directives"][0]["body"].is_object());
    assert!(!expected["references"].as_array().unwrap().is_empty());

    // The org-charter block is generated by the reference importer; the native
    // block must be equal, including the policy source label and required list.
    let native_org = serde_json::to_value(sk_doctrine::org_charter_block(&fixture.project))
        .expect("native org block");
    assert_eq!(native_org, oracle["org_charter"]);
    assert_eq!(
        native_org["packs"][0]["required_directives"],
        json!(["DIRECTIVE_003"])
    );
}

#[test]
fn catalogue_fallback_defaults_match_the_oracle_exactly() {
    // No activation ledger at all: every per-kind key is absent, so each kind
    // resolves its catalogue default independently. This is the default project
    // state the review found under-delivered, and it exercises the canonical
    // model dump across the entire built-in directive/tactic catalogue.
    let fixture = fixture();
    fs::remove_file(fixture.project.join(".kittify/charter/activation.yaml")).unwrap();
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    assert_eq!(
        native["directives_source"].as_str(),
        Some("catalog_fallback+charter+project_local")
    );

    // Non-vacuity: the catalogue fallback really delivers both catalogues with
    // canonical nested bodies (not a handful of hub artifacts).
    let tactics = expected["tactics"].as_array().expect("tactics array");
    let directives = expected["directives"].as_array().expect("directives array");
    assert!(tactics.len() >= 30, "only {} tactics", tactics.len());
    assert!(
        directives.len() >= 30,
        "only {} directives",
        directives.len()
    );
    for entry in tactics.iter().chain(directives.iter()) {
        assert!(
            entry["body"].is_object(),
            "missing body for {}",
            entry["id"]
        );
    }
}

#[test]
fn non_git_project_without_local_directives_degrades_like_the_oracle() {
    // A supported non-Git project root has no charter-config resolution: the
    // reference's `load_directives_config` and `resolve_project_governance`
    // both raise `NotInsideRepositoryError` (the canonical-root gate), and
    // `_load_project_directives_with_diagnostics` catches it. The documented
    // contract is `directives_source: null` (provenance unavailable),
    // `all_directives: []`, no resolution diagnostics and no governance
    // references. Inventing the catalogue resolution here was the residual.
    let fixture = fixture_with_git(false);
    fs::remove_file(fixture.project.join(".kittify/charter/charter.yaml")).unwrap();
    // No activation ledger either: the action-bundle seed walk still resolves
    // its per-kind catalogue defaults, so typed delivery is the full catalogue
    // even though the directive PROVENANCE resolution is unavailable.
    fs::remove_file(fixture.project.join(".kittify/charter/activation.yaml")).unwrap();
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_eq!(native["all_directives"], json!([]));
    assert_eq!(native["directives_source"], Value::Null);
    assert_eq!(native["diagnostics"], json!([]));
    assert_eq!(native["governance_references"], json!([]));
    // The oracle agrees: this is not a native-only invention.
    assert_eq!(expected["all_directives"], json!([]));
    assert_eq!(expected["directives_source"], Value::Null);
    assert_eq!(expected["diagnostics"], json!([]));

    // Non-vacuity: the degrade is limited to provenance. Typed delivery is
    // still the full catalogue with bodies and a real link set, so this is not
    // a refusal of the supported non-Git input and not a quietly emptied
    // payload.
    assert_eq!(native["mode"], json!("bootstrap"));
    assert!(
        native["tactics"].as_array().unwrap().len() >= 30,
        "typed delivery is unaffected by the provenance degrade"
    );
    assert!(native["directives"].as_array().unwrap().len() >= 30);
    assert!(!native["references"].as_array().unwrap().is_empty());
}

#[test]
fn non_git_project_with_local_directives_reports_no_resolution_provenance() {
    // The same degrade with an authored local directive, a charter selection
    // and governance references present on disk. `load_directives_config`
    // anchors on the same canonical root as the resolver, so it raises too and
    // NO directly-loaded local directive reaches `all_directives`; the
    // charter file itself is still described by `project_charter` (that block
    // reads the root directly).
    let fixture = fixture_with_git(false);
    assert!(
        fixture
            .project
            .join(".kittify/charter/charter.yaml")
            .is_file(),
        "the authored charter really carries a selection, a local directive and references"
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_eq!(native["all_directives"], json!([]));
    assert_eq!(native["directives_source"], Value::Null);
    assert_eq!(native["diagnostics"], json!([]));
    assert_eq!(native["governance_references"], json!([]));
    assert_eq!(expected["all_directives"], json!([]));
    assert_eq!(expected["directives_source"], Value::Null);
    assert_eq!(native["project_charter"]["present"], json!(true));
    // Non-vacuity: the authored activation ledger still delivers its selected
    // artifacts, so the degrade did not empty typed delivery.
    let directives = native["directives"].as_array().unwrap();
    assert_eq!(directives.len(), 1);
    assert_eq!(directives[0]["id"], json!("DIRECTIVE_001"));
    assert!(directives[0]["body"].is_object());
    assert!(!native["tactics"].as_array().unwrap().is_empty());
    assert!(!native["references"].as_array().unwrap().is_empty());
}

#[test]
fn git_control_resolves_the_same_authored_fixture() {
    // The control for both non-Git cases: identical authored content inside a
    // Git repository keeps the resolved provenance, the local directive and
    // the governance references. The degrade is a property of the canonical
    // root gate, not of the fixture content.
    let fixture = fixture();
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, &oracle["payload"]);
    assert_eq!(
        native["directives_source"],
        json!("activation+charter+project_local")
    );
    let local = native["all_directives"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["id"] == "DIRECTIVE_009")
        .expect("the authored local directive resolves in a Git checkout");
    assert_eq!(local["source"], json!("project"));
    assert_eq!(local["title"], json!("Local"));
    assert_eq!(
        native["governance_references"].as_array().unwrap().len(),
        2,
        "both authored governance references are reported"
    );
}

#[test]
fn explicit_empty_directive_allow_keeps_the_independent_tactic_catalogue() {
    // An explicit, present, EMPTY directive allow list deactivates every
    // directive even though the org pack requires none. The tactic key is
    // ABSENT, so it resolves its catalogue default independently: the reference
    // `_seed_sets` is per kind, so the tactic catalogue is still delivered from
    // its own roots. This is the Python-settled answer behind the unit test
    // `explicit_empty_directive_allow_denies_directives_but_not_the_tactic_catalogue`
    // (it is not a weakened deny rule: the empty directive list really does
    // deliver no directive).
    let fixture = fixture();
    set_org_charter(&fixture, "schema_version: 2\norg_name: Acme\n");
    set_ledger(
        &fixture,
        "activated_directives: []\nmission_type_activations: [software-dev]\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    assert_eq!(native["directives"], json!([]));
    assert_eq!(expected["directives"], json!([]));
    // The directive branch is the explicit (empty) activation selection, never
    // the catalogue fallback; the project-local directive ids are still
    // resolved into `all_directives` only.
    let source = expected["directives_source"]
        .as_str()
        .expect("oracle directives_source");
    assert!(
        source.starts_with("activation") && !source.starts_with("catalog_fallback"),
        "unexpected directive branch {source:?}"
    );
    let tactics = expected["tactics"].as_array().expect("tactics array");
    assert!(
        tactics.len() >= 30,
        "the absent tactic key resolves the catalogue default: {} tactics",
        tactics.len()
    );
    assert!(
        tactics.iter().all(|entry| entry["body"].is_object()),
        "every catalogue tactic carries its model-dump body"
    );
}

#[test]
fn a_denied_tactic_only_removes_itself_from_the_catalogue_default() {
    // The unit test `activation_filter_removes_deactivated_artifacts` denies one
    // tactic with no allow keys at all. The reference still resolves the tactic
    // catalogue default and delivers every other tactic; asserting the whole
    // array empty (the pre-fix unit expectation) contradicted the oracle, while
    // asserting only "the denied id is gone" would be too weak. This pins both
    // halves against the oracle.
    let fixture = fixture();
    set_ledger(
        &fixture,
        "activated_directives: [DIRECTIVE_001]\ndeactivated_tactics: [aggregate-boundary-design]\nmission_type_activations: [software-dev]\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    let oracle_tactics = expected["tactics"].as_array().expect("tactics array");
    assert!(
        oracle_tactics.len() >= 30,
        "the denial does not collapse the catalogue: {} tactics",
        oracle_tactics.len()
    );
    let delivered = |value: &Value| {
        value["tactics"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry["id"] == "aggregate-boundary-design")
    };
    assert!(!delivered(expected), "the oracle honours the deny");
    assert!(!delivered(&native), "the native deny matches the oracle");
}

#[test]
fn selected_non_hub_tactic_is_delivered_inline_like_the_oracle() {
    let fixture = fixture();
    set_ledger(
        &fixture,
        "activated_directives: [DIRECTIVE_001]\nactivated_tactics: [aggregate-boundary-design]\nmission_type_activations: [software-dev]\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);

    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    let expected_tactics = expected["tactics"].as_array().unwrap();
    assert!(
        expected_tactics
            .iter()
            .any(|entry| entry["id"] == "aggregate-boundary-design"),
        "the oracle-fixed non-hub tactic must be delivered"
    );
    let delivered = native["tactics"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["id"] == "aggregate-boundary-design")
        .expect("the activated non-hub tactic is delivered from its own root");
    assert_eq!(delivered["delivery"], "inline");
    assert!(delivered["body"].is_object());
}

#[test]
fn org_required_roots_are_independent_of_the_action_bundle() {
    // No `activated_tactics` key (the tactic catalogue default applies) and a
    // project deny naming a non-hub tactic the org pack requires. The org floor
    // must net that deny, so the tactic stays in the activation-filtered graph
    // and is delivered from the catalogue-default root. An explicit tactic allow
    // list would have already dropped it from the graph (the reference filters
    // before seeding), so an absent key is the state where the floor is the
    // only reason the artifact survives.
    let fixture = fixture();
    set_org_charter(
        &fixture,
        "schema_version: 2\norg_name: Acme\nrequired_directives: [DIRECTIVE_003]\nrequired_tactics: [aggregate-boundary-design]\ngovernance_policies:\n  - field: commits\n    value: signed\n",
    );
    set_ledger(
        &fixture,
        "activated_directives: [DIRECTIVE_001]\ndeactivated_tactics: [aggregate-boundary-design]\nmission_type_activations: [software-dev]\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert!(
        native["tactics"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry["id"] == "aggregate-boundary-design"),
        "the org-required non-hub tactic must survive the stale deny and be delivered"
    );

    // Control: drop the org requirement and re-run both sides. The deny now
    // stands, so the tactic disappears from the delivered set — it was the
    // org-required floor, not an incidental action edge, that delivered it.
    set_org_charter(
        &fixture,
        "schema_version: 2\norg_name: Acme\nrequired_directives: [DIRECTIVE_003]\ngovernance_policies:\n  - field: commits\n    value: signed\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert!(
        !native["tactics"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry["id"] == "aggregate-boundary-design"),
        "without the org requirement the denied non-hub tactic is not delivered"
    );
}

