#[test]
fn profile_schema_accepts_alias_and_populate_by_name_spellings() {
    let fixture = fixture();
    // Author the profile with the Python FIELD names rather than the kebab-case
    // aliases: the reference model sets `populate_by_name=True`, so both spell
    // the same profile. The native loader must not skip it.
    let alias_dir = fixture.packs.join("alias-src");
    let alias_file = alias_dir.join("agent_profiles/aliased.agent.yaml");
    write(
        &alias_file,
        "profile_id: aliased\nname: Aliased\nschema_version: '1.0'\nroles: [reviewer]\npurpose: alias parity\nspecialization:\n  primary_focus: review\nrouting_priority: 7\nmax_concurrent_tasks: 3\nself_review_protocol:\n  steps:\n    - name: check\n      gate: must-pass\ndirective_references:\n  - code: '001'\n    name: arch\n    rationale: because\nmode_defaults:\n  - mode: careful\n    description: thorough\n    use_case: risky change\n",
    );
    let oracle = run_oracle(&fixture, ALIAS_PROFILE_ORACLE_SCRIPT);
    assert_eq!(oracle["accepted"], json!(true));

    // `ProfileRepository` loads `<root>/agent_profiles/*.agent.yaml`.
    let repository = ProfileRepository::load(&alias_dir, &[], None).expect("profiles");
    assert!(
        repository.skipped().is_empty(),
        "{:?}",
        repository.skipped()
    );
    let profile = repository.get_str("aliased").expect("alias profile loads");
    assert_eq!(
        profile.scalar_id(),
        Some(oracle["profile_id"].as_str().unwrap().to_owned())
    );
    // The body is the reference model's `by_alias=True` view, so a snake_case
    // authored field reads back under its kebab-case serialization alias.
    assert_eq!(
        profile
            .body
            .get("routing-priority")
            .and_then(serde_yaml_ng::Value::as_i64),
        oracle["routing_priority"].as_i64()
    );
    assert_eq!(
        profile
            .body
            .get("max-concurrent-tasks")
            .and_then(serde_yaml_ng::Value::as_i64),
        oracle["max_concurrent_tasks"].as_i64()
    );
    assert_eq!(
        profile
            .body
            .get("self-review-protocol")
            .and_then(|value| value.get("steps"))
            .and_then(|value| value.get(0))
            .and_then(|value| value.get("gate"))
            .and_then(serde_yaml_ng::Value::as_str),
        oracle["self_review_gate"].as_str()
    );
    assert_eq!(
        profile
            .body
            .get("directive-references")
            .and_then(|value| value.get(0))
            .and_then(|value| value.get("code"))
            .and_then(serde_yaml_ng::Value::as_str),
        oracle["directive_code"].as_str()
    );
    assert_eq!(oracle["conflicting_role"], json!("refused"));

    // The reference refuses a profile declaring both `role:` and `roles:`; the
    // native loader skips and records it rather than silently picking one.
    let conflicting_dir = fixture.packs.join("conflicting-src");
    write(
        &conflicting_dir.join("agent_profiles/conflicting.agent.yaml"),
        "profile-id: conflicting\nname: Conflicting\npurpose: p\nrole: reviewer\nroles: [architect]\nspecialization:\n  primary-focus: review\n",
    );
    let conflicting = ProfileRepository::load(&conflicting_dir, &[], None).expect("profiles");
    assert!(conflicting.get_str("conflicting").is_none());
    assert_eq!(
        conflicting
            .skipped()
            .iter()
            .filter(|entry| entry.profile_id.as_deref() == Some("conflicting"))
            .count(),
        1
    );
}

