#[test]
fn malformed_required_field_keeps_the_rest_of_the_org_floor() {
    // Base declares a required directive; the overlay declares a MALFORMED
    // `required_directives` scalar (only that field must drop) and a valid
    // `required_tactics` list. The reference reads each field independently and
    // still applies the overlay's `extends: base` contribution.
    let temp = tempfile::tempdir().unwrap();
    let packs = temp.path().join("packs");
    let project = temp.path().join("project");
    copy_tree(
        &support::repository_root().join("packs/built-in"),
        &packs.join("built-in"),
    );
    init_project(&project);
    let base = packs.join("base");
    let overlay = packs.join("overlay");
    for (name, root, charter) in [
        ("base", &base, "required_directives: [DIRECTIVE_001]\n"),
        (
            "overlay",
            &overlay,
            "extends: base\nrequired_directives: DIRECTIVE_003\nrequired_tactics: [acceptance-test-first]\n",
        ),
    ] {
        write(
            &root.join("pack.yaml"),
            &format!("name: {name}\npack_level: org\n"),
        );
        write(
            &root.join("drg/fragment.yaml"),
            &format!("pack_name: {name}\nnodes: []\nedges: []\n"),
        );
        write(&root.join("org-charter.yaml"), charter);
    }
    write(
        &project.join(".kittify/config.yaml"),
        &format!(
            "charter_packs:\n  org:\n    packs:\n      - name: base\n        local_path: {}\n      - name: overlay\n        local_path: {}\n",
            base.display(),
            overlay.display()
        ),
    );
    write(&project.join("docs/context.md"), "context\n");
    // A stale project deny naming the org-required tactic: the floor must net it.
    write(
        &project.join(".kittify/charter/activation.yaml"),
        "deactivated_tactics: [acceptance-test-first]\nmission_type_activations: [software-dev]\n",
    );
    let fixture = Fixture {
        _temp: temp,
        project,
        packs,
    };

    let oracle = run_oracle(&fixture, FLOOR_ORACLE_SCRIPT);
    let mut identity = IdentityIndex::from_roots(
        &fixture.packs.join("built-in"),
        &[base.clone(), overlay.clone()],
        None,
    );
    scan_all(&mut identity);
    for kind in [ArtifactKind::Directive, ArtifactKind::Tactic] {
        let key = kind.canonical();
        let tokens = read_org_required_tokens(&fixture.project, kind, false).unwrap();
        assert_eq!(
            json!(tokens),
            oracle["tokens"][key],
            "{key} required tokens"
        );
        let provenance =
            read_org_required_provenance(&fixture.project, kind, &identity, false).unwrap();
        let native: serde_json::Map<String, Value> = provenance
            .into_iter()
            .map(|(stem, packs)| {
                (
                    stem,
                    Value::Array(
                        packs
                            .into_iter()
                            .map(|pack| json!([pack.pack, pack.via]))
                            .collect(),
                    ),
                )
            })
            .collect();
        assert_eq!(
            Value::Object(native),
            oracle["provenance"][key],
            "{key} required provenance"
        );
    }
    // The malformed directive field is dropped on both sides, but the overlay's
    // valid tactic requirement survives and the base directive still applies.
    assert_eq!(
        oracle["tokens"]["directive"],
        json!(["DIRECTIVE_001"]),
        "only the malformed overlay directive field is dropped"
    );
    assert_eq!(oracle["tokens"]["tactic"], json!(["acceptance-test-first"]));

    // The floor nets the stale deny, so the tactic is not effectively denied.
    let ledger = load_activation_ledger(&fixture.project).unwrap();
    let floor = required_floor(&fixture.project, &identity)
        .unwrap()
        .into_map();
    let denied = sk_doctrine::deactivated_urns_with_floor(&ledger, &identity, &floor).unwrap();
    assert!(
        !denied.contains("tactic:acceptance-test-first"),
        "the org-required tactic's floor entry must net the stale deny: {denied:?}"
    );
}

