#[test]
fn synthesis_lock_path_and_contention_match_python() {
    let fixture = fixture();
    let oracle = run_oracle(
        &fixture,
        r#"
import json, os
from pathlib import Path
from charter.activation.synthesizer.synthesis_lock import synthesis_lock_path
print(json.dumps({"path": str(synthesis_lock_path(Path.cwd()))}))
"#,
    );
    let native_path = synthesis_lock_path(&fixture.project).expect("native lock path");
    assert_eq!(
        native_path.display().to_string(),
        oracle["path"].as_str().unwrap()
    );

    // A Python process holds the canonical lock; the native transaction cannot
    // acquire it (bounded wait) and refuses instead of writing beside it.
    let mut child = Command::new(support::python())
        .arg("-c")
        .arg(
            r#"
import sys
from pathlib import Path
from charter.activation.synthesizer.synthesis_lock import synthesis_lock
with synthesis_lock(Path.cwd()):
    print("HELD", flush=True)
    sys.stdin.readline()
"#,
        )
        .current_dir(&fixture.project)
        .envs(support::oracle_env(&fixture.packs))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn lock holder");
    let mut stdout = BufReader::new(child.stdout.take().expect("stdout"));
    let mut line = String::new();
    stdout.read_line(&mut line).expect("read holder line");
    assert_eq!(line.trim(), "HELD");

    let error = acquire_synthesis_lock(&fixture.project, Duration::from_millis(200))
        .expect_err("the Python holder blocks the native lock");
    assert!(matches!(error, DoctrineError::SynthesisLockHeld { .. }));

    // A transaction begun under contention refuses at commit, not silently.
    let transaction = ActivationTransaction::begin(&fixture.project).expect("observe");
    let plan = ActivationPlan {
        yaml_key: "activated_tactics".to_owned(),
        new_list: Some(vec!["acceptance-test-first".to_owned()]),
        ..ActivationPlan::default()
    };
    let error = transaction.commit(&plan).expect_err("contended commit");
    assert!(matches!(error, DoctrineError::SynthesisLockHeld { .. }));

    child
        .stdin
        .as_mut()
        .expect("stdin")
        .write_all(b"release\n")
        .expect("release holder");
    drop(child.stdin.take());
    let status = child.wait().expect("holder exit");
    assert!(status.success());

    // After release the same transaction commits under the shared lock.
    let transaction = ActivationTransaction::begin(&fixture.project).expect("observe");
    transaction.commit(&plan).expect("uncontended commit");
    let ledger = load_activation_ledger(&fixture.project).expect("ledger");
    assert_eq!(
        ledger.allow_for(ArtifactKind::Tactic),
        Some(&["acceptance-test-first".to_owned()][..])
    );
    let resolved = resolve_activation_source(&fixture.project).expect("source");
    assert!(resolved.ledger_exists);
}

