const ORACLE_TOLERANT_SCRIPT: &str = r#"
import json
from pathlib import Path
from charter.activation.context import build_charter_context_json

repo = Path.cwd()
try:
    payload = build_charter_context_json(repo, action="implement", mission_type="software-dev")
except Exception as exc:
    print(json.dumps({
        "raised": True,
        "error": type(exc).__name__,
        "code": getattr(exc, "code", None),
        "message": str(exc),
    }))
else:
    print(json.dumps({"raised": False, "payload": payload}))
"#;

/// A built-in artifact body re-declared under *id* (the body stays valid).
fn body_with_id(relative: &str, id: &str) -> String {
    let text = fs::read_to_string(
        support::repository_root()
            .join("packs/built-in")
            .join(relative),
    )
    .unwrap_or_else(|error| panic!("read built-in {relative}: {error}"));
    let mut out = String::new();
    let mut replaced = false;
    for line in text.lines() {
        if !replaced && line.starts_with("id: ") {
            out.push_str(&format!("id: {id}\n"));
            replaced = true;
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    assert!(replaced, "{relative} declares no id");
    out
}

fn write_org(fixture: &Fixture, relative: &str, text: &str) {
    write(&fixture.packs.join("org").join(relative), text);
}

fn write_project(fixture: &Fixture, relative: &str, text: &str) {
    write(
        &fixture
            .project
            .join(".kittify/charter-packs")
            .join(relative),
        text,
    );
}

fn entries_with_id<'a>(payload: &'a Value, key: &str, id: &str) -> Vec<&'a Value> {
    payload[key]
        .as_array()
        .unwrap_or_else(|| panic!("{key} is not an array"))
        .iter()
        .filter(|entry| entry["id"] == id)
        .collect()
}

#[test]
fn absent_key_catalogue_default_includes_org_and_project_graph_artifacts() {
    // N1: the absent-key catalogue default is `_graph_and_catalog_default_ids`
    // — every node of the kind the merged graph declares (built-in, ORG and
    // PROJECT) unioned with the built-in catalogue — not "built-in only". The
    // default project state (no activation ledger) must therefore deliver org
    // and project graph artifacts rather than silently dropping them.
    let fixture = fixture();
    fs::remove_file(fixture.project.join(".kittify/charter/activation.yaml")).unwrap();
    write_org(
        &fixture,
        "directives/ORG_D777.directive.yaml",
        &body_with_id(
            "directives/001-architectural-integrity-standard.directive.yaml",
            "ORG_D777",
        ),
    );
    write_org(
        &fixture,
        "tactics/org-default-tactic.tactic.yaml",
        &body_with_id(
            "tactics/adversarial-qa-handoff.tactic.yaml",
            "org-default-tactic",
        ),
    );
    write_org(
        &fixture,
        "drg/fragment.yaml",
        "pack_name: acme\nnodes:\n  - id: ORG_D777\n    kind: directives\n    title: Graph label directive\n    body_path: directives/ORG_D777.directive.yaml\n  - id: org-default-tactic\n    kind: tactics\n    title: Graph label tactic\n    body_path: tactics/org-default-tactic.tactic.yaml\nedges: []\n",
    );
    write_project(
        &fixture,
        "directive/PROJ_D500.directive.yaml",
        &body_with_id(
            "directives/003-decision-documentation-requirement.directive.yaml",
            "PROJ_D500",
        ),
    );
    write_project(
        &fixture,
        "tactic/proj-default-tactic.tactic.yaml",
        &body_with_id(
            "tactics/testing/acceptance-test-first.tactic.yaml",
            "proj-default-tactic",
        ),
    );
    write_project(
        &fixture,
        "project.graph.yaml",
        "schema_version: '1.0'\ngenerated_at: STATIC\ngenerated_by: drg-migration-v1\nnodes:\n- urn: directive:PROJ_D500\n  kind: directive\n  label: Project graph label directive\n- urn: tactic:proj-default-tactic\n  kind: tactic\n  label: Project graph label tactic\nedges: []\n",
    );

    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);
    assert_eq!(
        native["directives_source"],
        json!("catalog_fallback+charter+project_local")
    );
    for (key, id) in [
        ("directives", "ORG_D777"),
        ("tactics", "org-default-tactic"),
        ("directives", "PROJ_D500"),
        ("tactics", "proj-default-tactic"),
    ] {
        assert_eq!(
            entries_with_id(&native, key, id).len(),
            1,
            "the absent-key default must deliver {key} {id}"
        );
        assert_eq!(entries_with_id(expected, key, id).len(), 1);
    }
    // The catalogue is the full built-in set plus exactly the two extra nodes
    // of each kind — this is not a partial or single-artifact delivery.
    assert!(native["directives"].as_array().unwrap().len() >= 36);
    assert!(native["tactics"].as_array().unwrap().len() >= 116);
    // The built-in criterion still governs the diagnostic count even though the
    // default itself includes org/project ids (exact message is checked above).
    assert!(
        native["diagnostics"]
            .as_array()
            .unwrap()
            .iter()
            .any(|diagnostic| diagnostic["message"]
                .as_str()
                .is_some_and(|message| message.contains("(14 paradigms)")))
    );

    // Control: an explicit activation of the same org artifacts still matches
    // exactly, so the fix changed only the catalogue-default seed.
    set_ledger(
        &fixture,
        "activated_directives: [ORG_D777]\nactivated_tactics: [org-default-tactic]\nmission_type_activations: [software-dev]\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert_eq!(entries_with_id(&native, "directives", "ORG_D777").len(), 1);
    assert_eq!(
        entries_with_id(&native, "tactics", "org-default-tactic").len(),
        1
    );
}

#[test]
fn retired_governance_doctrine_key_is_a_typed_refusal_not_a_degrade() {
    // N2a: `governance.doctrine` is the retired selection key. The reference
    // HARD-REFUSES it (`require_canonical_governance` ->
    // `ActiveCharterConfigError` / `ACTIVE_CHARTER_CONFIG_INVALID`); it never
    // returns a payload that honours or silently drops the retired selection.
    let fixture = fixture();
    write(
        &fixture.project.join(".kittify/charter/charter.yaml"),
        "governance:\n  doctrine:\n    selected_directives: [DIRECTIVE_024]\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_TOLERANT_SCRIPT);
    assert_eq!(oracle["raised"], json!(true));
    assert_eq!(oracle["code"], json!("ACTIVE_CHARTER_CONFIG_INVALID"));

    let error = native_payload_result(&fixture).expect_err("the retired key must refuse");
    assert!(
        matches!(error, DoctrineError::RetiredGovernanceSelection { .. }),
        "{error:?}"
    );
    assert_eq!(
        error.reference_code(),
        Some("ACTIVE_CHARTER_CONFIG_INVALID")
    );
    let message = error.to_string();
    assert!(message.contains("governance.doctrine"), "{message}");
    assert!(message.contains("spec-kitty upgrade"), "{message}");
    assert!(
        message.contains("docs/migrations/charter-pack-cutover.md"),
        "{message}"
    );

    // Control: the same authored content with the canonical `governance.charter`
    // key resolves (the refusal is about the retired key, not the file).
    write(
        &fixture.project.join(".kittify/charter/charter.yaml"),
        "governance:\n  charter:\n    selected_directives: [DIRECTIVE_024]\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert_eq!(
        native["directives_source"],
        json!("activation+charter+project_local")
    );
}

#[test]
fn retired_governance_key_on_a_non_git_root_degrades_like_the_oracle() {
    // The refusal is gated on the canonical-root read: outside a Git checkout
    // the reference's governance read raises `NotInsideRepositoryError` before
    // it can see the retired key, and the documented degrade (local-only, null
    // source) applies instead. Refusing here would be a new refusal on a
    // supported input.
    let fixture = fixture_with_git(false);
    write(
        &fixture.project.join(".kittify/charter/charter.yaml"),
        "governance:\n  doctrine:\n    selected_directives: [DIRECTIVE_024]\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_TOLERANT_SCRIPT);
    assert_eq!(oracle["raised"], json!(false), "{oracle}");
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert_eq!(native["all_directives"], json!([]));
    assert_eq!(native["directives_source"], Value::Null);
    assert_eq!(native["diagnostics"], json!([]));
    assert_eq!(native["governance_references"], json!([]));
    // Non-vacuity: typed delivery is unaffected.
    assert_eq!(
        entries_with_id(&native, "directives", "DIRECTIVE_001").len(),
        1
    );
}

#[test]
fn malformed_governance_and_directives_shapes_degrade_to_local_only() {
    // N2b: a malformed governance/directives shape is NOT a refusal and NOT a
    // resolved set. The reference catches the resolver failure and returns the
    // directly-loaded local directives with `directives_source: null`, no
    // resolution diagnostics and no governance references. The previous native
    // behaviour kept its activation base and reported a resolved-looking
    // provenance.
    let local = "directives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n";
    let cases: [(&str, String, Vec<&str>); 7] = [
        (
            "governance is a list",
            format!("governance: []\n{local}"),
            vec!["DIRECTIVE_009"],
        ),
        (
            "governance.charter is a scalar",
            format!("governance:\n  charter: 5\n{local}"),
            vec!["DIRECTIVE_009"],
        ),
        (
            "selected_directives is a scalar",
            format!("governance:\n  charter:\n    selected_directives: not-a-list\n{local}"),
            vec!["DIRECTIVE_009"],
        ),
        (
            "selected_directives holds a non-string",
            format!("governance:\n  charter:\n    selected_directives: [DIRECTIVE_024, 5]\n{local}"),
            vec!["DIRECTIVE_009"],
        ),
        (
            "directives is a bare sequence",
            "governance:\n  charter:\n    selected_directives: [DIRECTIVE_024]\ndirectives:\n  - id: DIRECTIVE_009\n    title: Local\n".to_owned(),
            vec![],
        ),
        (
            "directives entry has no title",
            "governance:\n  charter:\n    selected_directives: [DIRECTIVE_024]\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      description: Local\n".to_owned(),
            vec![],
        ),
        (
            "charter.yaml is unparseable",
            "governance: [unclosed\n  - :\n".to_owned(),
            vec![],
        ),
    ];
    for (label, charter, expected_local_ids) in cases {
        let fixture = fixture();
        write(
            &fixture.project.join(".kittify/charter/charter.yaml"),
            &charter,
        );
        let oracle = run_oracle(&fixture, ORACLE_TOLERANT_SCRIPT);
        assert_eq!(oracle["raised"], json!(false), "{label}: {oracle}");
        let expected = &oracle["payload"];
        let native = native_payload(&fixture);
        assert_payload_matches_oracle(&native, expected);
        assert_diagnostics_match_oracle(&native, expected);
        assert_eq!(native["directives_source"], Value::Null, "{label}");
        assert_eq!(native["diagnostics"], json!([]), "{label}");
        assert_eq!(native["governance_references"], json!([]), "{label}");
        let ids: Vec<&str> = native["all_directives"]
            .as_array()
            .unwrap()
            .iter()
            .map(|entry| entry["id"].as_str().unwrap())
            .collect();
        assert_eq!(ids, expected_local_ids, "{label}");
        let expected_ids: Vec<&str> = expected["all_directives"]
            .as_array()
            .unwrap()
            .iter()
            .map(|entry| entry["id"].as_str().unwrap())
            .collect();
        assert_eq!(expected_ids, expected_local_ids, "{label} (oracle)");
        // The authored activation still delivers, so the degrade is limited to
        // the provenance resolution.
        assert_eq!(
            entries_with_id(&native, "directives", "DIRECTIVE_001").len(),
            1,
            "{label}"
        );
    }
}

#[test]
fn typed_entry_titles_come_from_the_artifact_model_not_the_graph_label() {
    // N3: the reference `artifact_to_dict` reads the artifact MODEL's `title`
    // (then `name`), never the DRG node label. Every graph label below differs
    // from the body title, so a label-first native DTO reddens.
    let fixture = fixture();
    let mut ledger = String::from(
        "activated_directives: [ORG_D777]\nactivated_tactics: [org-label-tactic]\nmission_type_activations: [software-dev]\n",
    );
    ledger.push_str("activated_styleguides: [org-label-styleguide]\nactivated_toolguides: [org-label-toolguide]\nactivated_procedures: [org-label-procedure]\n");
    set_ledger(&fixture, &ledger);
    write_org(
        &fixture,
        "directives/ORG_D777.directive.yaml",
        &body_with_id(
            "directives/001-architectural-integrity-standard.directive.yaml",
            "ORG_D777",
        ),
    );
    write_org(
        &fixture,
        "tactics/org-label-tactic.tactic.yaml",
        &body_with_id(
            "tactics/adversarial-qa-handoff.tactic.yaml",
            "org-label-tactic",
        ),
    );
    write_org(
        &fixture,
        "styleguides/org-label-styleguide.styleguide.yaml",
        &body_with_id(
            "styleguides/aggregate-design-rules.styleguide.yaml",
            "org-label-styleguide",
        ),
    );
    write_org(
        &fixture,
        "toolguides/org-label-toolguide.toolguide.yaml",
        &body_with_id(
            "toolguides/contextive.toolguide.yaml",
            "org-label-toolguide",
        ),
    );
    write_org(
        &fixture,
        "procedures/org-label-procedure.procedure.yaml",
        &body_with_id(
            "procedures/adversarial-squad-deployment.procedure.yaml",
            "org-label-procedure",
        ),
    );
    write_org(
        &fixture,
        "drg/fragment.yaml",
        "pack_name: acme\nnodes:\n  - id: ORG_D777\n    kind: directives\n    title: Graph label directive\n    body_path: directives/ORG_D777.directive.yaml\n  - id: org-label-tactic\n    kind: tactics\n    title: Graph label tactic\n    body_path: tactics/org-label-tactic.tactic.yaml\n  - id: org-label-styleguide\n    kind: styleguides\n    title: Graph label styleguide\n    body_path: styleguides/org-label-styleguide.styleguide.yaml\n  - id: org-label-toolguide\n    kind: toolguides\n    title: Graph label toolguide\n    body_path: toolguides/org-label-toolguide.toolguide.yaml\n  - id: org-label-procedure\n    kind: procedures\n    title: Graph label procedure\n    body_path: procedures/org-label-procedure.procedure.yaml\nedges:\n  - source: directive:ORG_D777\n    target: styleguide:org-label-styleguide\n    relation: requires\n  - source: directive:ORG_D777\n    target: toolguide:org-label-toolguide\n    relation: requires\n  - source: action:software-dev/implement\n    target: procedure:org-label-procedure\n    relation: scope\n",
    );

    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);

    for (key, id, title) in [
        ("directives", "ORG_D777", "Architectural Integrity Standard"),
        ("tactics", "org-label-tactic", "Adversarial QA Handoff"),
        (
            "styleguides",
            "org-label-styleguide",
            "Aggregate Design Rules",
        ),
        ("toolguides", "org-label-toolguide", "Contextive"),
        (
            "procedures",
            "org-label-procedure",
            "Adversarial Squad Deployment",
        ),
    ] {
        let entry = entries_with_id(&native, key, id);
        assert_eq!(entry.len(), 1, "{key} {id} must be delivered");
        assert_eq!(entry[0]["title"], json!(title), "{key} {id} title");
        assert_ne!(
            entry[0]["title"],
            json!(format!("Graph label {}", key.trim_end_matches('s'))),
            "{key} {} must not use the DRG label",
            id
        );
        assert_eq!(entries_with_id(expected, key, id)[0]["title"], json!(title));
    }
}

#[test]
fn unknown_selection_and_project_local_merge_diagnostics_match_the_oracle_exactly() {
    // N4: one unresolved ACTIVATION token produced three
    // `UNKNOWN_SELECTION_DROPPED` entries natively; the reference emits one,
    // for the unresolved CHARTER SELECTION (unknown activation tokens are only
    // logged). The project-local merge message is the reference's
    // "Merged N project-local directive(s) onto the ... set", not the
    // "Charter selected ..." wording.
    let fixture = fixture();
    set_ledger(
        &fixture,
        "activated_directives: [DIRECTIVE_999]\nmission_type_activations: [software-dev]\n",
    );
    write(
        &fixture.project.join(".kittify/charter/charter.yaml"),
        "governance:\n  charter:\n    selected_directives: [DIRECTIVE_024, DIRECTIVE_888]\ndirectives:\n  directives:\n    - id: DIRECTIVE_009\n      title: Local\n      description: Authored locally\n",
    );
    let oracle = run_oracle(&fixture, ORACLE_SCRIPT);
    let expected = &oracle["payload"];
    let native = native_payload(&fixture);
    assert_payload_matches_oracle(&native, expected);
    assert_diagnostics_match_oracle(&native, expected);

    let diagnostics = native["diagnostics"].as_array().unwrap();
    let unknown: Vec<&Value> = diagnostics
        .iter()
        .filter(|diagnostic| diagnostic["code"] == "UNKNOWN_SELECTION_DROPPED")
        .collect();
    assert_eq!(
        unknown.len(),
        1,
        "exactly one UNKNOWN_SELECTION_DROPPED for the unresolved charter selection: {diagnostics:?}"
    );
    let message = unknown[0]["message"].as_str().unwrap();
    assert!(message.contains("DIRECTIVE_888"), "{message}");
    assert!(
        !message.contains("DIRECTIVE_999"),
        "an unknown ACTIVATION token is not a payload diagnostic: {message}"
    );
    let local = diagnostics
        .iter()
        .find(|diagnostic| {
            diagnostic["code"] == "SELECTION_MERGED"
                && diagnostic["message"]
                    .as_str()
                    .is_some_and(|message| message.contains("project-local"))
        })
        .expect("project-local merge diagnostic");
    assert_eq!(
        local["message"],
        json!(
            "Merged 1 project-local directive(s) onto the activation+charter set: DIRECTIVE_009."
        )
    );
}
